const FB_CONFIG = { apiKey: "AIzaSyDTFiy07edMQHrF6Qc3K2CcLmWc3Z5-vPk", authDomain: "questa-c7bff.firebaseapp.com", projectId: "questa-c7bff", appId: "1:748121591788:web:3775a3301f0c2bb7ec7ac9" };

// Load Firebase from CDN so it works in both the artifact preview and Vite
let _fbAuth = null;
let _fbReady = null;
let _fbDb = null;
function loadFirebase() {
  if (_fbReady) return _fbReady;
  _fbReady = new Promise((resolve) => {
    if (typeof window === "undefined") return resolve(null);
    if (window.__firebase_auth__) return resolve(window.__firebase_auth__);
    const loadScript = (src) => new Promise((res, rej) => {
      if (document.querySelector(`script[src="${src}"]`)) return res();
      const s = document.createElement("script"); s.src = src; s.onload = res; s.onerror = rej;
      document.head.appendChild(s);
    });
    Promise.all([
      loadScript("https://www.gstatic.com/firebasejs/10.12.2/firebase-app-compat.js"),
      loadScript("https://www.gstatic.com/firebasejs/10.12.2/firebase-auth-compat.js"),
      loadScript("https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore-compat.js"),
    ]).then(() => {
      try {
        const app = firebase.apps.length ? firebase.apps[0] : firebase.initializeApp(FB_CONFIG);
        _fbAuth = firebase.auth(app);
        _fbDb = firebase.firestore(app);
        window.__firebase_auth__ = _fbAuth;
        resolve(_fbAuth);
      } catch(e) { resolve(null); }
    }).catch(() => resolve(null));
  });
  return _fbReady;
}
const getFbAuth = () => loadFirebase();
const getDb = async () => { await loadFirebase(); return _fbDb; };
const fbSignOut = async () => { const a = await loadFirebase(); if (a) await a.signOut(); };

// ── Firestore sync helpers ──────────────────────────────────────
const SYNC_KEYS = ["user", "roadmaps", "completed", "notes", "nodeChecks", "saved", "savedProfs", "portfolio"];

async function loadUserData(uid) {
  try {
    const db = await getDb();
    if (!db) return null;
    const doc = await db.collection("users").doc(uid).get();
    return doc.exists ? doc.data() : null;
  } catch { return null; }
}

let _syncTimer = null;
async function saveUserData(uid, data) {
  try {
    const db = await getDb();
    if (!db || !uid) return;
    await db.collection("users").doc(uid).set(data, { merge: true });
  } catch {}
}

function debouncedSync(uid, data) {
  if (_syncTimer) clearTimeout(_syncTimer);
  _syncTimer = setTimeout(() => saveUserData(uid, data), 1500);
}
