/* ═══ MODULE: config/brand.js ═══ */
const BRAND = {
  name: "QUESTA",
  // Official wordmark (user-provided), embedded as data URIs.
  // dark variant for light surfaces · light variant for dark surfaces.
  logoUrl: "data:image/png;base64,",
  logoUrlLight: "data:image/png;base64,",
};

async function callAI(system, messages, opts = {}) {
  const ac = new AbortController();
  const tm = setTimeout(() => ac.abort(), 60000);
  let r;
  try {
    r = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ system, messages, ...(opts.maxTokens ? { maxTokens: opts.maxTokens } : {}), ...(opts.stream ? { stream: true } : {}) }),
      signal: ac.signal,
    });
  } catch (e) {
    clearTimeout(tm);
    if (e.name === "AbortError") throw new Error("Request timed out. Please try again.");
    throw e;
  }
  clearTimeout(tm);
  if (!r.ok) {
    if (r.status === 429 || r.status === 503) {
      const err = new Error("TRAFFIC_HIGH");
      err.traffic = true;
      throw err;
    }
    let errMsg = "AI request failed";
    try { const eb = await r.json(); errMsg = eb.error || errMsg; } catch {}
    throw new Error(errMsg);
  }
  // Streaming mode: call onChunk for each piece, return full text
  if (opts.stream && opts.onChunk) {
    const reader = r.body.getReader();
    const decoder = new TextDecoder();
    let buf = "", full = "";
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      const lines = buf.split("\n");
      buf = lines.pop() || "";
      for (const line of lines) {
        if (!line.startsWith("data: ")) continue;
        const d = line.slice(6).trim();
        if (!d || d === "[DONE]") continue;
        try {
          const j = JSON.parse(d);
          if (j.error) throw new Error(j.error);
          if (j.text) { full += j.text; opts.onChunk(full); }
        } catch (e) { if (e.message && !e.message.includes("JSON")) throw e; }
      }
    }
    if (!full) throw new Error("Empty response from AI");
    return full;
  }
  const data = await r.json();
  if (!data.text) throw new Error("Empty response from AI");
  return data.text;
}

