/* ═══ MODULE: components/LearningPage.jsx ═══ */
function BackToHome() {
  const { t, go } = useQ();
  return (
    <button onClick={() => go("home")} className="q-mono" style={{ fontSize: 11, color: "#2b3634", background: "none", border: "none", cursor: "pointer", letterSpacing: "0.1em", padding: 0, marginBottom: 24, display: "inline-flex", alignItems: "center", gap: 0 }}>
      {String.fromCharCode(171)} {t.backHome}
    </button>
  );
}

function LearningPage() {
  const { t, lang, go, completed, setPathId } = useQ();
  return (
    <div className="max-w-4xl mx-auto px-6" style={{ paddingTop: "clamp(24px,4vh,48px)", paddingBottom: "clamp(40px,6vh,64px)", position: "relative" }}>
      <BackToHome />
      <div style={{ marginBottom: "clamp(24px,4vh,40px)" }}>
        <div className="q-mono" style={{ fontSize: 11, letterSpacing: "0.2em", color: "#2b3634", marginBottom: 16 }}>[ ARCHIVE ]</div>
        <h1 className="q-display" style={{ fontSize: "clamp(36px,5vw,64px)", fontWeight: 800, color: "#2b3634", letterSpacing: "-0.04em", lineHeight: 1.05 }}>{t.subjectsTitle}</h1>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 0 }}>
        {DB.subjects.map((s, i) => (
          (() => {
            const allN = (s.branches || []).reduce((a, b) => a + b.nodes.length, 0);
            const doneN = (s.branches || []).reduce((a, b) => a + b.nodes.filter(n => completed[n.id]).length, 0);
            return (
          <button key={s.id} onClick={() => { setPathId(null); go("subject", s.id); }}
            className="text-left"
            style={{ display: "flex", alignItems: "center", gap: "clamp(16px,3vw,32px)", padding: "clamp(20px,3vh,32px) 0", borderBottom: i < DB.subjects.length - 1 ? "1px solid rgba(43,54,52,.08)" : "none", cursor: "pointer", transition: "opacity .2s", width: "100%" }}
            onMouseOver={e => e.currentTarget.style.opacity = "0.6"}
            onMouseOut={e => e.currentTarget.style.opacity = "1"}>
            <span className="q-mono" style={{ fontSize: 12, color: "#2b3634", fontWeight: 500, flexShrink: 0, width: 36 }}>{String(i + 1).padStart(3, "0")}</span>
            <div style={{ flex: 1, minWidth: 0 }}>
              <span className="q-display" style={{ fontSize: "clamp(22px,3vw,36px)", fontWeight: 700, color: "#2b3634", letterSpacing: "-0.03em" }}>{s.name[lang] || s.name.en}</span>
              {doneN > 0 && (
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 6 }}>
                  <div style={{ width: 48, height: 2, background: "rgba(43,54,52,.15)", borderRadius: 1, position: "relative" }}>
                    <div style={{ position: "absolute", left: 0, top: 0, height: 2, width: Math.round(doneN / allN * 100) + "%", background: "rgba(43,54,52,.5)", borderRadius: 1 }} />
                    <div style={{ position: "absolute", top: -3, height: 8, width: 1.5, background: "rgba(43,54,52,.6)", left: Math.round(doneN / allN * 100) + "%", transform: "translateX(-50%)" }} />
                  </div>
                  <span className="q-mono" style={{ fontSize: 10, color: "rgba(43,54,52,.45)", letterSpacing: "0.08em" }}>{String(doneN).padStart(2, "0")} / {String(allN).padStart(2, "0")}</span>
                </div>
              )}
            </div>
            <span style={{ fontSize: 16, color: "#2b3634", flexShrink: 0 }}>{String.fromCharCode(187)}</span>
          </button>
            );
          })()
        ))}
      </div>
    </div>
  );
}

/* ═══ MODULE: components/SubjectPage.jsx ═══ */
function Breadcrumb({ items }) {
  return (
    <nav className="flex items-center flex-wrap gap-1.5 text-sm font-bold mb-5">
      {items.map((it, i) => (
        <span key={i} className="flex items-center gap-1.5">
          {i > 0 && <ChevronRight size={14} className="text-slate-300" />}
          {it.onClick ? (
            <button onClick={it.onClick} className="text-indigo-300 hover:q-ink transition-colors">{it.label}</button>
          ) : (
            <span className="q-ink">{it.label}</span>
          )}
        </span>
      ))}
    </nav>
  );
}

/* Resolve a subject's path branch-ids into branch objects */
function pathBranches(s, path) {
  return (path.branches || []).map((bid) => s.branches.find((b) => b.id === bid)).filter(Boolean);
}

